mapper.select:
select
    *
from
    student_wrongChoice_Question
where
    questionId = #{questionId}
and
    studenterId = #{studenterId}
order by id desc
limit 1;

select a.id as courseId, a.curriculum as courseName, a.author, a.synopsis, a.biography, a.h_picture as image, a.picture, a.subjectid, a.integral as score, (select subjectName from common_course_subject where id = a.subjectId) as subjectName, (select count(*) from common_student_browsing_history where courseid = a.id) as pageViews, (select count(*) from common_course_knowledge where courseId = a.id and isLast = 1) as knowNumber, (select if(count(*)>1,1,0) from common_course_purchase where courseid = a.id and studenterId = #{studenterId} and status = 1) as isPay, (select if(count(*)>1,1,0) from common_collect_course where courseId=a.id and studenterId = #{studenterId} and deleted = 0) as isCollection from common_course a where deleted = 0
and subjectId = #{subjectId}
ORDER BY createdt DESC
